sealed class Outcome240 {
    data class Success(val payload: String) : Outcome240()
    data object Failure : Outcome240()
}

fun describe240(outcome: Outcome240): String = when (outcome) {
    is Outcome240.Success -> outcome.payload
    Outcome240.Failure -> "failed"
}
fun <T, R> List<T>.mapChecked241(transform: (T) -> R): List<R> {
    val result = mutableListOf<R>()
    for (item in this) {
        result.add(transform(item))
    }
    return result
}
